class NumMatrix {
    private int[][] prefix;

    public NumMatrix(int[][] matrix) {
        int m = matrix.length;
        int n = matrix[0].length;
        prefix = new int[m + 1][n + 1];
        for (int row = 1; row <= m; row++) {
            for (int col = 1; col <= n; col++) {
                prefix[row][col] = matrix[row - 1][col - 1]
                        + prefix[row - 1][col]
                        + prefix[row][col - 1]
                        - prefix[row - 1][col - 1];
            }
        }
    }

    public int sumRegion(int row1, int col1, int row2, int col2) {
        return prefix[row2 + 1][col2 + 1]
                - prefix[row1][col2 + 1]
                - prefix[row2 + 1][col1]
                + prefix[row1][col1];
    }
}

class NumMatrix {
    private int[][] rowPrefix;

    public NumMatrix(int[][] matrix) {
        int m = matrix.length;
        int n = matrix[0].length;
        rowPrefix = new int[m][n + 1];
        for (int row = 0; row < m; row++) {
            for (int col = 0; col < n; col++) {
                rowPrefix[row][col + 1] = rowPrefix[row][col] + matrix[row][col];
            }
        }
    }

    public int sumRegion(int row1, int col1, int row2, int col2) {
        int sum = 0;
        for (int row = row1; row <= row2; row++) {
            sum += rowPrefix[row][col2 + 1] - rowPrefix[row][col1];
        }
        return sum;
    }
}

