class NumMatrix {
    private int rows;
    private int cols;
    private int[][] bit;

    public NumMatrix(int[][] matrix) {
        rows = matrix.length;
        cols = matrix[0].length;
        bit = new int[rows + 1][cols + 1];
        for (int row = 0; row < rows; row++) {
            for (int col = 0; col < cols; col++) {
                add(row + 1, col + 1, matrix[row][col]);
            }
        }
    }

    public int sumRegion(int row1, int col1, int row2, int col2) {
        return prefix(row2 + 1, col2 + 1)
                - prefix(row1, col2 + 1)
                - prefix(row2 + 1, col1)
                + prefix(row1, col1);
    }

    private void add(int row, int col, int delta) {
        for (int r = row; r <= rows; r += r & -r) {
            for (int c = col; c <= cols; c += c & -c) {
                bit[r][c] += delta;
            }
        }
    }

    private int prefix(int row, int col) {
        int sum = 0;
        for (int r = row; r > 0; r -= r & -r) {
            for (int c = col; c > 0; c -= c & -c) {
                sum += bit[r][c];
            }
        }
        return sum;
    }
}

class NumMatrix {
    private int[][] matrix;

    public NumMatrix(int[][] matrix) {
        this.matrix = new int[matrix.length][matrix[0].length];
        for (int row = 0; row < matrix.length; row++) {
            this.matrix[row] = matrix[row].clone();
        }
    }

    public int sumRegion(int row1, int col1, int row2, int col2) {
        int sum = 0;
        for (int row = row1; row <= row2; row++) {
            for (int col = col1; col <= col2; col++) {
                sum += matrix[row][col];
            }
        }
        return sum;
    }
}
